import{_ as s,o,c as r,a2 as a}from"./chunks/framework.BXzK3EA4.js";const t="/assets/image-key20250306.ChjOyAZP.png",p="/assets/image-key2025030601.GjVJGvem.png",i="/assets/image-key2025030602.CVD9Zim8.png",d="/assets/image-key2025030603.CNYC4aNY.png",u=JSON.parse('{"title":"如何生成SSH密钥对","description":"","frontmatter":{"title":"如何生成SSH密钥对"},"headers":[],"relativePath":"ops-knowledge-base/vps/generate-ssh-key-pair.md","filePath":"ops-knowledge-base/vps/generate-ssh-key-pair.md","lastUpdated":1788259091000}'),n={name:"ops-knowledge-base/vps/generate-ssh-key-pair.md"};function l(c,e,h,g,_,m){return o(),r("div",null,[...e[0]||(e[0]=[a('<p>使用密钥进行远程连接的主要目的是提高安全性、简化登录流程，并支持自动化操作。相比于密码认证，密钥认证具有以下优势：</p><ol><li>更高的安全性，抵抗暴力破解和中间人攻击。</li><li>无需记忆密码，避免密码泄露。</li><li>支持自动化任务和批量管理。</li><li>提供细粒度的访问控制和权限管理。</li></ol><p>因此，密钥认证是远程连接服务器的最佳实践，尤其是在生产环境或需要高安全性的场景中。</p><p>本文介绍从生成密钥到如何使用密钥进行远程登录介绍</p><h2 id="一-生成-ssh-密钥对" tabindex="-1">一. 生成 SSH 密钥对 <a class="header-anchor" href="#一-生成-ssh-密钥对" aria-label="Permalink to &quot;一. 生成 SSH 密钥对&quot;">​</a></h2><ol><li>在 <strong>客户端机器</strong>（即你要用来登录远程服务器的机器）上执行以下命令：</li></ol><p>#ssh-keygen -t rsa -b 4096</p><p>或者，使用 更安全的 Ed25519 算法（推荐）：</p><p>#ssh-keygen -t ed25519</p><ol start="2"><li>在生成密钥时，你会被要求输入一个 <strong>密码短语（passphrase）</strong>。这不是必需的，但建议为密钥添加密码以提高安全性。如果不想每次登录时输入密码短语，可以直接按回车跳过。</li></ol><p>示例：</p><p><img src="'+t+'" alt=""></p><p>生成密钥后会在用户的 <code>~/.ssh</code> 目录下生成两个文件：</p><ul><li><strong>私钥</strong>：<code>id_rsa</code> 或 <code>id_ed25519</code></li><li><strong>公钥</strong>：<code>id_rsa.pub</code> 或 <code>id_ed25519.pub</code></li><li><strong>私钥（id_rsa）</strong> 仅存放在本地，<strong>公钥（id_rsa.pub）</strong> 需要上传到服务器</li></ul><p><img src="'+p+'" alt=""></p><h2 id="二-将公钥复制到远程服务器" tabindex="-1">二. 将公钥复制到远程服务器 <a class="header-anchor" href="#二-将公钥复制到远程服务器" aria-label="Permalink to &quot;二. 将公钥复制到远程服务器&quot;">​</a></h2><p>接下来，你需要将 <strong>公钥</strong> 复制到远程服务器的 <code>~/.ssh/authorized_keys</code> 文件中。</p><h3 id="方法-1-使用-ssh-copy-id-推荐" tabindex="-1"><strong>方法 1：使用</strong> <code>ssh-copy-id</code><strong>（推荐）</strong> <a class="header-anchor" href="#方法-1-使用-ssh-copy-id-推荐" aria-label="Permalink to &quot;**方法 1：使用** `ssh-copy-id`**（推荐）**&quot;">​</a></h3><p><code>ssh-copy-id</code> 是最简便的复制公钥的方法。假设你的远程服务器 IP 地址为 <code>192.168.1.100</code>，用户名是 <code>root</code>，执行以下命令：</p><p>#ssh-copy-id -i ~/.ssh/id_rsa.pub <a href="mailto:root@192.168.1.100" target="_blank" rel="noreferrer">root@192.168.1.100</a></p><p>或者：</p><p>#ssh-copy-id -i ~/.ssh/id_ed25519.pub <a href="mailto:root@192.168.1.100" target="_blank" rel="noreferrer">root@192.168.1.100</a></p><p>然后输入 <strong>远程服务器的密码</strong>，完成后，公钥会被自动添加到远程服务器的 <code>~/.ssh/authorized_keys</code> 文件中。</p><p>示例：</p><p><img src="'+i+'" alt=""></p><p><img src="'+d+'" alt=""></p><h3 id="方法-2-手动复制公钥" tabindex="-1"><strong>方法 2：手动复制公钥</strong> <a class="header-anchor" href="#方法-2-手动复制公钥" aria-label="Permalink to &quot;**方法 2：手动复制公钥**&quot;">​</a></h3><p>如果 <code>ssh-copy-id</code> 命令不可用，可以手动将 <strong>公钥</strong> 复制到远程服务器：</p><ol><li>在本地执行以下命令，查看公钥内容：</li></ol><p>#cat ~/.ssh/id_rsa.pub</p><p>或</p><p>#cat ~/.ssh/id_ed25519.pub</p><ol start="2"><li>登录到远程服务器：</li></ol><p>#ssh <a href="mailto:root@192.168.1.100" target="_blank" rel="noreferrer">root@192.168.1.100</a></p><pre><code> 3. 在远程服务器上，编辑 `~/.ssh/authorized_keys` 文件：\n</code></pre><p>#mkdir -p ~/.ssh</p><p>#chmod 700 ~/.ssh</p><p>#vi ~/.ssh/authorized_keys</p><pre><code> 4. 将 **本地公钥** 内容粘贴到 `authorized_keys` 文件中，然后保存并退出。\n</code></pre><p>修改权限：</p><p>#chmod 600 ~/.ssh/authorized_keys</p><p><a href="https://billing.raksmart.com/whmcs/index.php?rp=/knowledgebase/977/%E5%A6%82%E4%BD%95%E4%BD%BF%E7%94%A8%E7%A7%81%E9%92%A5%E8%BF%9B%E8%A1%8C%E8%BF%9C%E7%A8%8B%E7%99%BB%E5%BD%95.html" target="_blank" rel="noreferrer"><strong>接下来会从macOS系统、windows系统和不同的远程工具介绍如何通过私钥进行远程登录。</strong></a></p>',42)])])}const b=s(n,[["render",l]]);export{u as __pageData,b as default};
